import { n as validateEmbedding } from "./embeddings-AyrkCWRj.js";
//#region src/lib/retrieval/embedding-provider.server.ts
function readConfig() {
	const baseUrl = typeof process !== "undefined" && (process.env.SIRIUS_EMBEDDING_BASE_URL?.trim() || process.env.SIRIUS_AI_BASE_URL?.trim()) || null;
	const apiKey = typeof process !== "undefined" && (process.env.SIRIUS_EMBEDDING_API_KEY?.trim() || process.env.SIRIUS_AI_API_KEY?.trim()) || null;
	const model = typeof process !== "undefined" && process.env.SIRIUS_EMBEDDING_MODEL?.trim() || "text-embedding-3-small";
	return {
		configured: Boolean(baseUrl && apiKey),
		baseUrl,
		apiKey,
		model
	};
}
function embeddingProviderConfigured() {
	return readConfig().configured;
}
function createOpenAICompatibleEmbeddingProvider() {
	const cfg = readConfig();
	if (!cfg.configured || !cfg.baseUrl || !cfg.apiKey) return null;
	return {
		id: "openai_compatible",
		modelId: cfg.model,
		expectedDimensions: null,
		async embed(texts) {
			if (texts.length === 0) return [];
			const limited = texts.slice(0, 16).map((t) => t.slice(0, 4e3));
			const controller = new AbortController();
			const timeout = setTimeout(() => controller.abort(), 3e4);
			try {
				const url = cfg.baseUrl.replace(/\/$/, "") + "/embeddings";
				const res = await fetch(url, {
					method: "POST",
					headers: {
						"Content-Type": "application/json",
						Authorization: `Bearer ${cfg.apiKey}`
					},
					body: JSON.stringify({
						model: cfg.model,
						input: limited
					}),
					signal: controller.signal
				});
				if (!res.ok) throw new Error(`embedding_http_${res.status}`);
				const rows = (await res.json()).data ?? [];
				const out = [];
				for (let i = 0; i < limited.length; i++) {
					const vec = (rows.find((r) => r.index === i) ?? rows[i])?.embedding;
					if (!validateEmbedding(vec)) throw new Error("invalid_embedding_vector");
					out.push(vec);
				}
				return out;
			} finally {
				clearTimeout(timeout);
			}
		}
	};
}
//#endregion
export { createOpenAICompatibleEmbeddingProvider, embeddingProviderConfigured };
